import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes — 2025","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-2025.md","filePath":"aireblock-releases/AireFrame/aireframe-2025.md","lastUpdated":1786565768000}`),a={name:`aireblock-releases/AireFrame/aireframe-2025.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes-—-2025" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes — 2025</span> <a class="header-anchor" href="#aireframe-release-notes-—-2025" aria-label="Permalink to “AireFrame Release Notes — 2025”">​</a></h1><p>This page contains the AireFrame releases published during 2025.</p><h2 id="version-2-41-0-—-array-datapoint-aggregation" tabindex="-1">Version 2.41.0 — Array Datapoint Aggregation <a class="header-anchor" href="#version-2-41-0-—-array-datapoint-aggregation" aria-label="Permalink to “Version 2.41.0 — Array Datapoint Aggregation”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 15, 2025</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add array datapoint aggregation support in pipeline</li><li>Support for expired status for AireFlow tasks</li></ul><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Accessibility improvements</li><li>Improve search result matching</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where Liquid colour formatting wasn&#39;t being applied in some visualisations</li><li>Fix issue where the documentation bot wasn&#39;t working on configuration pages</li><li>Fix issue where dragging a widget into a dashboard while filtered would insert the incorrect widget</li><li>Fix incorrect colours displaying on a bar chart series</li><li>Fix issue where reference data wasn&#39;t being displayed on a line graph visualisation</li><li>Fix linked data set filtering</li></ul><h2 id="version-2-40-0-—-configuration-page-design-improvements" tabindex="-1">Version 2.40.0 — Configuration Page Design Improvements <a class="header-anchor" href="#version-2-40-0-—-configuration-page-design-improvements" aria-label="Permalink to “Version 2.40.0 — Configuration Page Design Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 27, 2025</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Rework configuration page layout for improved usability</li><li>Improve speed of visualisation updates</li></ul><h2 id="version-2-39-0-—-performance-improvements" tabindex="-1">Version 2.39.0 — Performance Improvements <a class="header-anchor" href="#version-2-39-0-—-performance-improvements" aria-label="Permalink to “Version 2.39.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 17, 2025</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Reduce lag when using the structural entity selector for large structures</li><li>Improve visualisation update speeds</li><li>Normalise dashboard selector sizing</li></ul><h2 id="version-2-38-0-—-custom-theming" tabindex="-1">Version 2.38.0 — Custom Theming <a class="header-anchor" href="#version-2-38-0-—-custom-theming" aria-label="Permalink to “Version 2.38.0 — Custom Theming”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 6, 2025</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added custom theming support</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve offline detection performance</li><li>Improve data visualisation designer</li><li>Improve search matching</li><li>Improve upsert API return value</li><li>Improve subject list configuration form</li><li>Improve configuration import</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where custom colours were not reflected in chart legend</li><li>Fix issue where clicking the home button removes dashboard selection in subject list</li><li>Fix issue where configuration imports were failing</li><li>Fix issue in pipeline designer where <code>max by</code> could not be used within a group</li></ul><h2 id="version-2-37-0-—-performance-improvements" tabindex="-1">Version 2.37.0 — Performance Improvements <a class="header-anchor" href="#version-2-37-0-—-performance-improvements" aria-label="Permalink to “Version 2.37.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 20, 2025</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add file upload virus scanning</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve speed of cross-subject visualisation updates</li><li>Improve offline detection to handle different devices better</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where clicking back within the visualisation designer would lose all changes</li><li>Fix issue where subject list tooltip did not strip HTML tags</li><li>Fix issue where download subject for offline button was shown on the portal site</li><li>Fix issue where a date time custom field value could not be saved or rehydrated</li><li>Fix issue where linked data sets would show irrelevant actions</li></ul><h2 id="version-2-36-0-—-visualisation-update-performance-improvements" tabindex="-1">Version 2.36.0 — Visualisation Update Performance Improvements <a class="header-anchor" href="#version-2-36-0-—-visualisation-update-performance-improvements" aria-label="Permalink to “Version 2.36.0 — Visualisation Update Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 23, 2025</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve speed of visualisation pending updates</li></ul><h2 id="version-2-35-0-—-offline-mode" tabindex="-1">Version 2.35.0 — Offline Mode <a class="header-anchor" href="#version-2-35-0-—-offline-mode" aria-label="Permalink to “Version 2.35.0 — Offline Mode”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 11, 2025</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add offline mode support</li></ul><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Reduce asset sizes for faster load times</li><li>Move docs bot button into the top navigation bar</li><li>Improve order by icon distinction</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where subject configuration could not be saved under certain conditions</li><li>Fix issue where users with no groups could still see tenant-level dashboards</li><li>Fix issue where phone number field had a zero-adding behaviour in certain cases</li><li>Fix issue where newly created data sets would not appear in the pipeline designer without a page refresh</li><li>Fix issue where pipeline title could not be updated</li><li>Fix issue where the Liquid widget preview would not render like the final widget</li></ul><h2 id="version-2-34-0" tabindex="-1">Version 2.34.0 <a class="header-anchor" href="#version-2-34-0" aria-label="Permalink to “Version 2.34.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 11, 2025</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add docs bot to configuration pages</li><li>Add ability to search users list by email</li></ul><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Rework order by UI in tables</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix data extract selector quirkiness</li><li>Fix issue where URL parameters were lost after sign-in</li><li>Fix issue where changing the subject data source did not clear the group caches</li><li>Fix issue where the UI could freeze when a group aggregate was used on a data extract with many fields</li><li>Fix issue where if multiple partial subject update requests were fired at the same time, only the last update would be applied</li></ul><h2 id="version-2-33-0-—-linked-data-sets" tabindex="-1">Version 2.33.0 — Linked Data Sets <a class="header-anchor" href="#version-2-33-0-—-linked-data-sets" aria-label="Permalink to “Version 2.33.0 — Linked Data Sets”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 16, 2025</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add Linked Data Sets</li><li>Allow clipboard write inside iframes</li><li>Allow dashboard to be created on initial load without clicking the create button</li></ul><h2 id="version-2-32-0-—-stacked-data-sets" tabindex="-1">Version 2.32.0 — Stacked Data Sets <a class="header-anchor" href="#version-2-32-0-—-stacked-data-sets" aria-label="Permalink to “Version 2.32.0 — Stacked Data Sets”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 29, 2025</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add Stacked Data Sets</li><li>Split pipeline and visualisation configuration into separate items to allow pipeline reuse</li><li>Introduce subject banner query parameter for more control in embedded contexts</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve tree-shaking of libraries to reduce bundle size</li><li>Improve headless mode for more seamless embedding</li><li>Auto-redirect to AireIdentity if the user is not logged in and has a target URL</li><li>Improve collapse/expand icon hover state</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Remove stacked bar chart visualisation type</li></ul><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where structural entity keys were not validated on the subject upsert API</li><li>Fix issue where the parent structural entity was not validated on the structural entity upsert API</li><li>Fix issue where HTML was not rendered correctly in the portal subject selector</li><li>Fix issue where data sources with configuration values were not being sent correctly to the data source</li></ul><h2 id="version-2-31-0" tabindex="-1">Version 2.31.0 <a class="header-anchor" href="#version-2-31-0" aria-label="Permalink to “Version 2.31.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 1, 2025</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add search to data set list</li><li>Add login redirect URL validation</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve configuration navigation</li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where the create subject mutation was not validating location assignments</li><li>Fix issue where the group cache could still contain deleted structural entities</li><li>Fix issue where visualisations could not be created</li><li>Fix issue where the previous visualisation pipeline was shown when creating a new visualisation</li><li>Fix AireIdentity user management link</li><li>Fix issue where two subjects could be created with the same value for a unique field within a short time frame</li></ul><h2 id="version-2-30-0-—-performance-improvements" tabindex="-1">Version 2.30.0 — Performance Improvements <a class="header-anchor" href="#version-2-30-0-—-performance-improvements" aria-label="Permalink to “Version 2.30.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 4, 2025</p></blockquote><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Fix performance issues when navigating between the subject list and the subject page</li><li>Fix issue where form actions would sometimes not show due to slow query performance</li><li>Improve AireVault value fetching performance</li><li>Add report issue link to the footer</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where policy was not applied correctly to AireFlow actions</li><li>Fix issue where policy was not applied correctly to array custom fields</li></ul><h3 id="🔒-security" tabindex="-1">🔒 Security <a class="header-anchor" href="#🔒-security" aria-label="Permalink to “🔒 Security”">​</a></h3><ul><li>Fix PDF XSS vulnerability</li></ul><h2 id="version-2-29-0-—-liquid-expression-aggregator" tabindex="-1">Version 2.29.0 — Liquid Expression Aggregator <a class="header-anchor" href="#version-2-29-0-—-liquid-expression-aggregator" aria-label="Permalink to “Version 2.29.0 — Liquid Expression Aggregator”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 27, 2025</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add Liquid expression aggregator as an option in the visualisation pipeline</li><li>Allow a widget to be toggled on for the portal if it is off</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve AireFlow task update error messages</li><li>Subject updated events are now only sent if the subject custom field values have changed</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where the import configuration notification was not shown</li><li>Fix issue on the subject upsert API where a date time value was never valid</li><li>Fix issue where <code>| size</code> Liquid filter could not be used on a string value</li><li>Fix issue where client credentials calls would return 403 even after the permissions were granted</li><li>Fix issue where due date was not pulled through from form tasks</li></ul><h2 id="version-2-28-0-—-new-rest-apis" tabindex="-1">Version 2.28.0 — New REST APIs <a class="header-anchor" href="#version-2-28-0-—-new-rest-apis" aria-label="Permalink to “Version 2.28.0 — New REST APIs”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 27, 2025</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add API support for subject custom field array values</li><li>Add invite third-party users REST API</li><li>Set task owner type when actioning tasks</li><li>Allow customisation of x-axis label positioning on graphs</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where visualisation ordering did not work correctly for decimal values</li><li>Fix issue where it was impossible to clear the country code of a phone number</li><li>Fix issue where import would not update computed field Liquid expression if that was the only change</li><li>Fix issue where zooming out in the browser would un-align the widget header</li><li>Fix issue where <code>create:widget</code> permission was required to edit a widget</li><li>Fix issue where the visualisation pending update icon did not disappear after the update was complete</li><li>Fix subject upsert API validation</li></ul><h2 id="version-2-27-0-—-array-custom-fields-third-party-portal-users" tabindex="-1">Version 2.27.0 — Array Custom Fields &amp; Third-Party Portal Users <a class="header-anchor" href="#version-2-27-0-—-array-custom-fields-third-party-portal-users" aria-label="Permalink to “Version 2.27.0 — Array Custom Fields &amp; Third-Party Portal Users”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 11, 2025</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for array custom fields</li><li>Add support for inviting third-party users to the portal using an email address</li><li>Add support for re-inviting users to the portal</li><li>Add create structural entity REST API</li><li>Add subject portal users REST API</li></ul><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Apply series formatter to axis tick labels</li><li>Display resolved Liquid value in the applied filter UI</li><li>Widget filters are now encoded into the URL on the subject page</li><li>Add inline Liquid filter toggle button</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where data points were not shown if actions failed to load</li><li>Fix issue where subject upsert location could not be changed</li><li>Fix issue where changing page size did not reset back to the first page</li><li>Fix issue where changing the structure type of a structural entity could duplicate the custom field values</li></ul><h2 id="version-2-26-0-—-aireflow-form-tasks" tabindex="-1">Version 2.26.0 — AireFlow Form Tasks <a class="header-anchor" href="#version-2-26-0-—-aireflow-form-tasks" aria-label="Permalink to “Version 2.26.0 — AireFlow Form Tasks”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 16, 2025</p></blockquote><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for AireFlow form tasks</li><li>Show user job role in the navigation bar</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where form PDFs would not load</li><li>Fix loading UI bug on the subject overview page</li></ul><h2 id="version-2-25-0" tabindex="-1">Version 2.25.0 <a class="header-anchor" href="#version-2-25-0" aria-label="Permalink to “Version 2.25.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 9, 2025</p></blockquote><h3 id="✨-new-features-12" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-12" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add Subject Location Change APIs</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix iframe auto-popup on mobile devices</li><li>Fix issue where hovering on a bar chart with a custom colour would cause the bar to disappear</li><li>Fix issue where Liquid visualisations could show an error when the data was valid</li><li>Fix issue where a form could not be created if the user had a valid create form policy</li></ul>`,118)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};